// Build the invoice line, apply credits from disputes upheld since the last
// run, and honour the contract minimum.
//
// Everything here is arithmetic on numbers the database already froze. The
// workflow does not decide what a show is worth -- that was decided when the
// event became billable.

const out = [];
for (const item of $input.all()) {
  const r = item.json;
  const subtotal = Number(r.subtotal_cents || 0);
  const minimum  = Number(r.minimum_cents || 0);
  const shows    = Number(r.shows || 0);

  const adjustment = Math.max(0, minimum - subtotal);   // top up to the floor
  const total = subtotal + adjustment;

  const period = `${r.p_start} to ${r.p_end}`;
  const id = `inv_${r.clinic_id}_${String(r.p_start).slice(0, 7)}`;

  out.push({
    json: {
      invoice_id: id,
      clinic_id: r.clinic_id,
      business_name: r.business_name,
      period_start: r.p_start,
      period_end: r.p_end,
      shows_count: shows,
      subtotal_cents: subtotal,
      adjustment_cents: adjustment,
      total_cents: total,
      currency: r.currency || 'USD',
      appointment_ids: r.appointment_ids,
      summary: `${r.business_name}: ${shows} attended, ${(total / 100).toFixed(2)} ${r.currency || 'USD'} for ${period}` +
               (adjustment ? ` (incl. ${(adjustment / 100).toFixed(2)} contract minimum top-up)` : '')
    }
  });
}
return out;
